#!/usr/bin/env bash
# Documentation : partie « Domaine du club » en quatre chapitres.
# Prérequis : apply-fix-domaine.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-domaine.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/domaine/un-modele-qui-s-ouvre.mdx" 2>/dev/null | grep -qF "Le nom affiché n’est pas une identité"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "ensureStorageSegments" "packages/backend/src/modules/storage/storageSegments.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-domaine.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/domaine/comprendre-le-domaine.mdx")
EXPECT=("55804044234e:apps/web/content/docs/dev/domaine/comprendre-le-domaine.mdx")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=("apps/web/content/docs/dev/domaine/ce-que-voit-le-visiteur.mdx" "apps/web/content/docs/dev/domaine/les-conventions.mdx" "apps/web/content/docs/dev/domaine/un-modele-qui-s-ouvre.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Le nom affiché n’est pas une identité" "apps/web/content/docs/dev/domaine/un-modele-qui-s-ouvre.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/domaine"
