# Table de l'index : ligne « Domaine du club », quel que soit son texte actuel.
F=apps/web/content/docs/dev/index.mdx
if ! git diff --quiet HEAD -- "$F"; then echo "❌ $F a des modifications non commitées"; restore; exit 1; fi
MODIFIED+=("$F")
python3 - "$F" <<'PY2'
import re, sys
p = sys.argv[1]; s = open(p, encoding="utf-8").read()
new = "[\"Domaine du club\",\"En quatre chapitres : ce que le club modélise (disciplines, cours, stages, événements, actualités), les conventions qui les relient (heures HHMM, dates de séance, contenus, instructeurs, publication), un modèle qui s’ouvre (origines, événements, « au moins un des trois », dossiers figés), et ce que voit le visiteur (fiches, agenda, .ics).\",\"rédigée\"]"
s2, n = re.subn(r'\["Domaine du club","[^"]*","[^"]*"\]', lambda m: new, s)
assert n == 1, n
open(p, "w", encoding="utf-8").write(s2)
PY2
[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add -- "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
docs: partie « Domaine du club » en 4 chapitres — profondeur du tutoriel d'origine restaurée

Le tutoriel « Comprendre le domaine d'AKFC » est restauré en entier, découpé en quatre chapitres,
le code des extraits pris dans le projet actuel : ce que le club modélise, les conventions du
domaine, un modèle qui s'ouvre (origines, événements, « au moins un des trois », Seminar, slugs,
dossiers figés), ce que voit le visiteur (fiches, agenda, .ics, pied de page, vue d'ensemble).

